						["Color"] = color,
						["UnionColoring"] = false
					}
				}
			}
			_(args)
		end
	
		characterParts = {}
	
		for _, v in ipairs(player.Character:GetDescendants()) do
			if v:IsA("BasePart")
				and v.Name ~= "HumanoidRootPart"
				and not v:FindFirstAncestorOfClass("Accessory") then
	
				table.insert(characterParts, v)
	
				for _, child in ipairs(v:GetDescendants()) do
					if child:IsA("SpecialMesh") or child:IsA("BlockMesh") or child:IsA("CylinderMesh") then
						DestroyPart(child)
					end
				end
	
				AddMesh(v)
			end
