	local function C_b()
	local script = G2L["b"];
		local button = script.Parent
		--local input = CoolGui.Frame.Settings
		
		button.MouseButton1Down:connect(function()
			-- / Rocky2u's Command Script 2016
			-- /	ROBLOX			|	SethMilkman
			-- /	V3RMILLION		|	Rocky2u
			-- / pls no looking
