			function FIND_IN_TABLE(TABLE, NAME)
				for i,v in pairs(TABLE) do
					if v == NAME then
						return true
					end
				end
				return false
			end
		
			function GET_IN_TABLE(TABLE, NAME)
				for i = 1, #TABLE do
					if TABLE[i] == NAME then
						return i
					end
				end
				return false
			end
		
