					Reason_2.Text = "-MessagePosted function is invalid."
					Reason_2.TextColor3 = Color3.fromRGB(255, 0, 0)
					Reason_2.TextScaled = true
					Reason_2.TextSize = 50.000
					Reason_2.TextWrapped = true
