			localwin:drawButton(1/2, 'NoGrav', function()
		
				if lp.Character then
		
					for x,m in pairs(lp.Character:GetChildren()) do
		
						if m:IsA("BasePart") then
		
							local bf = Instance.new("BodyForce", m)
		
							bf.force = Vector3.new(0, 192.25, 0) * m:GetMass()
		
						end
		
