	-- StarterGui.CoolGui.Frame.Settings.SettingsButton.SettingsCloseOpen
	local function C_3d()
	local script = G2L["3d"];
		local TweenService = game:GetService("TweenService")
		local page = script.Parent.Parent
		local sbutton = script.Parent
		
		local cango = true
		local closedPosition = UDim2.new(1, -300, 0, 0)
		local openPosition = UDim2.new(1, 3, 0, 0)
		local tweenTime = 0.5
		
		local function togglePage()
			if not cango then return end
			cango = false
		
			if sbutton.Text == "<" then
				sbutton.Text = ">"
				local tween = TweenService:Create(page, TweenInfo.new(tweenTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Position = closedPosition})
				tween:Play()
				tween.Completed:Wait()
			else
				sbutton.Text = "<"
				local tween = TweenService:Create(page, TweenInfo.new(tweenTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Position = openPosition})
				tween:Play()
				tween.Completed:Wait()
			end
		
			cango = true
		end
		
		sbutton.MouseButton1Click:Connect(togglePage)
		
	end;
	task.spawn(C_3d);
