			function Part(Parent, Anchor, Collide, Tran, Ref, Color, X, Y, Z, Break)
		
				local p = Instance.new("Part")
		
				p.formFactor = "Custom"
		
				p.Anchored = Anchor
		
				p.CanCollide = Collide
		
				p.Transparency = Tran
		
				p.Reflectance = Ref
		
				p.BrickColor = BrickColor.new(Color)
		
				p.TopSurface = 0
		
				p.BottomSurface = 0
		
				p.Size = Vector3.new(X, Y, Z)
		
				if Break then
		
					p:BreakJoints()
		
				else p:MakeJoints() end
		
				p.Parent = Parent
		
				p.Locked = true
		
				return p
		
			end
		
		
		
