					Rh.Parent = Torso
					Lh.Part0 = Tor
					Rh.Part0 = Tor
					Lh.Part1 = Char["Left Leg"]
					Rh.Part1 = Char["Right Leg"]
					return Lh,Rh
				else
					Rh.Parent = nil
					Lh.Parent = nil
					local hl,hr = it("Weld",Torso),it("Weld",Torso)
					hl.Part0 = Fll
					hr.Part0 = Frl
					hl.Part1 = Char["Left Leg"]
					hr.Part1 = Char["Right Leg"]
					hr.C1 = cf(-0.5,1.75,0)
					hl.C1 = cf(0.5,1.75,0)
					return hl,hr
