			debrisEmitter.Lifetime = NumberRange.new(1, 2)  
			debrisEmitter.Speed = NumberRange.new(2, 5) 
			debrisEmitter.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.2), NumberSequenceKeypoint.new(1, 0)})  
			debrisEmitter.Acceleration = Vector3.new(0, -5, 0)  
			debrisEmitter.Rotation = NumberRange.new(0, 360)  
			debrisEmitter.RotSpeed = NumberRange.new(-50, 50)  
			debrisEmitter.Color = ColorSequence.new(Color3.fromRGB(0, 0, 0), Color3.fromRGB(50, 50, 50)) 
			debrisEmitter.LightEmission = 0.5  
		
		
		
			local fire = Instance.new("Fire")
			fire.Parent = UFO
			fire.Size = 2
			fire.Heat = 10
			fire.Color = Color3.fromRGB(0, 0, 0)
