				local offsetX = math.cos(math.rad(angle)) * radius
				local offsetZ = math.sin(math.rad(angle)) * radius
		
				UFO.Position = playerPosition + Vector3.new(offsetX, 0, offsetZ)
			end
		
		
		
		
		
			local UFO_attachment = Instance.new("Attachment")
