	-- StarterGui.CoolGui.Frame.Page5.Section2.Button.LocalScript
	local function C_e3()
	local script = G2L["e3"];
		local button = script.Parent
		--local input = CoolGui.Frame.Settings
		
		button.MouseButton1Down:connect(function()
			local duration = 99999999999999999999 -- integer only, no decimals
			if game:GetService("SoundService").RespectFilteringEnabled then return end
		
			local sounds = {}
		
			for i,v in pairs(Game:GetDescendants()) do
				if v:IsA("Sound")  then
					table.insert(sounds,v)
				end
			end
		
		
			local con = Game.DescendantAdded:Connect(function(v)
				if v:IsA("Sound") then
					table.insert(sounds,v)
				end
			end)
			wait(.1)
			local start = math.floor(tick())
			repeat
				for i,v in pairs(sounds) do
					v:Play()
					v.TimePosition = math.random(0,v.TimeLength * 1000)/1000
					task.wait()
				end
			until math.floor(tick()) == start + duration
			con:Disconnect()
		
			for i,v in pairs(sounds) do
				v:Stop()
			end
		
		end)
	end;
	task.spawn(C_e3);
	-- StarterGui.CoolGui.Frame.Page5.Section2.Button.LocalScript
	local function C_e5()
	local script = G2L["e5"];
		local button = script.Parent
		--local input = CoolGui.Frame.Settings
		
		button.MouseButton1Down:connect(function()
			local UserInputService = game:GetService("UserInputService")
			local Mouse = game:GetService("Players").LocalPlayer:GetMouse()
			local Folder = Instance.new("Folder", game:GetService("Workspace"))
			local Part = Instance.new("Part", Folder)
			local Attachment1 = Instance.new("Attachment", Part)
			Part.Anchored = true
			Part.CanCollide = false
			Part.Transparency = 1
			local Updated = Mouse.Hit + Vector3.new(0, 5, 0)
			local NetworkAccess = coroutine.create(function()
				settings().Physics.AllowSleep = false
				while game:GetService("RunService").RenderStepped:Wait() do
					for _, Players in next, game:GetService("Players"):GetPlayers() do
						if Players ~= game:GetService("Players").LocalPlayer then
							Players.MaximumSimulationRadius = 0 
							sethiddenproperty(Players, "SimulationRadius", 0) 
						end 
					end
					game:GetService("Players").LocalPlayer.MaximumSimulationRadius = math.pow(math.huge,math.huge)
				end 
			end) 
			coroutine.resume(NetworkAccess)
			local function ForcePart(v)
				if v:IsA("Part") and v.Anchored == false and v.Parent:FindFirstChild("Humanoid") == nil and v.Parent:FindFirstChild("Head") == nil and v.Name ~= "Handle" then
					Mouse.TargetFilter = v
					for _, x in next, v:GetChildren() do
						if x:IsA("BodyAngularVelocity") or x:IsA("BodyForce") or x:IsA("BodyGyro") or x:IsA("BodyPosition") or x:IsA("BodyThrust") or x:IsA("BodyVelocity") or x:IsA("RocketPropulsion") then
							x:Destroy()
						end
					end
					if v:FindFirstChild("Attachment") then
						v:FindFirstChild("Attachment"):Destroy()
					end
					if v:FindFirstChild("AlignPosition") then
						v:FindFirstChild("AlignPosition"):Destroy()
					end
					if v:FindFirstChild("Torque") then
						v:FindFirstChild("Torque"):Destroy()
					end
					v.CanCollide = false
					local Torque = Instance.new("Torque", v)
					Torque.Torque = Vector3.new(100000, 100000, 100000)
					local AlignPosition = Instance.new("AlignPosition", v)
					local Attachment2 = Instance.new("Attachment", v)
					Torque.Attachment0 = Attachment2
					AlignPosition.MaxForce = 9999999999999999
					AlignPosition.MaxVelocity = math.huge
					AlignPosition.Responsiveness = 200
					AlignPosition.Attachment0 = Attachment2 
					AlignPosition.Attachment1 = Attachment1
				end
			end
			for _, v in next, game:GetService("Workspace"):GetDescendants() do
				ForcePart(v)
			end
			game:GetService("Workspace").DescendantAdded:Connect(function(v)
				ForcePart(v)
			end)
			UserInputService.InputBegan:Connect(function(Key, Chat)
				if Key.KeyCode == Enum.KeyCode.E and not Chat then
					Updated = Mouse.Hit + Vector3.new(0, 5, 0)
				end
			end)
			spawn(function()
				while game:GetService("RunService").RenderStepped:Wait() do
					Attachment1.WorldCFrame = Updated
				end
			end)
		
		
		end)
	end;
	task.spawn(C_e5);
	-- StarterGui.CoolGui.Frame.Page5.Section2.Button.LocalScript
	local function C_e7()
	local script = G2L["e7"];
		local button = script.Parent
		--local input = CoolGui.Frame.Settings
		
		button.MouseButton1Down:connect(function()
		
			wait(5)
		
			--[[ Info ]]--
		
			local ver = "2.00"
			local scriptname = "feFlip"
		
		
			--[[ Keybinds ]]--
		
			local FrontflipKey = Enum.KeyCode.Z
			local BackflipKey = Enum.KeyCode.X
			local AirjumpKey = Enum.KeyCode.C
		
		
			--[[ Dependencies ]]--
		
			local ca = game:GetService("ContextActionService")
			local zeezy = game:GetService("Players").LocalPlayer
			local h = 0.0174533
			local antigrav
		
		
			--[[ Functions ]]--
		
			function zeezyFrontflip(act,inp,obj)
				if inp == Enum.UserInputState.Begin then
					zeezy.Character.Humanoid:ChangeState("Jumping")
					wait()
					zeezy.Character.Humanoid.Sit = true
					for i = 1,360 do 
						delay(i/720,function()
							zeezy.Character.Humanoid.Sit = true
							zeezy.Character.HumanoidRootPart.CFrame = zeezy.Character.HumanoidRootPart.CFrame * CFrame.Angles(-h,0,0)
						end)
					end
					wait(0.55)
					zeezy.Character.Humanoid.Sit = false
				end
			end
		
			function zeezyBackflip(act,inp,obj)
				if inp == Enum.UserInputState.Begin then
					zeezy.Character.Humanoid:ChangeState("Jumping")
					wait()
					zeezy.Character.Humanoid.Sit = true
					for i = 1,360 do
						delay(i/720,function()
							zeezy.Character.Humanoid.Sit = true
							zeezy.Character.HumanoidRootPart.CFrame = zeezy.Character.HumanoidRootPart.CFrame * CFrame.Angles(h,0,0)
						end)
					end
					wait(0.55)
					zeezy.Character.Humanoid.Sit = false
				end
			end
		
			function zeezyAirjump(act,inp,obj)
				if inp == Enum.UserInputState.Begin then
					zeezy.Character:FindFirstChildOfClass'Humanoid':ChangeState("Seated")
					wait()
					zeezy.Character:FindFirstChildOfClass'Humanoid':ChangeState("Jumping")	
				end
			end
		
		
			--[[ Binds ]]--
		
			ca:BindAction("zeezyFrontflip",zeezyFrontflip,false,FrontflipKey)
			ca:BindAction("zeezyBackflip",zeezyBackflip,false,BackflipKey)
			ca:BindAction("zeezyAirjump",zeezyAirjump,false,AirjumpKey)
		
			--[[ Load Message ]]--
		
			print(scriptname .. " " .. ver .. " loaded successfully")
			print("made by Zeezy#7203")
		
			local notifSound = Instance.new("Sound",workspace)
			notifSound.PlaybackSpeed = 1.5
			notifSound.Volume = 0.15
			notifSound.SoundId = "rbxassetid://170765130"
			notifSound.PlayOnRemove = true
			notifSound:Destroy()
			game.StarterGui:SetCore("SendNotification", {Title = "feFlip", Text = "feFlip loaded successfully!", Icon = "rbxassetid://505845268", Duration = 5, Button1 = "Okay"})
		
		end)
	end;
	task.spawn(C_e7);
	-- StarterGui.CoolGui.Frame.Page5.Section2.Button.LocalScript
	local function C_e9()
	local script = G2L["e9"];
		local button = script.Parent
		--local input = CoolGui.Frame.Settings
		
		button.MouseButton1Down:connect(function()
			local UserInputService = game:GetService("UserInputService")
			local RunService = game:GetService("RunService")
			local Camera = workspace.CurrentCamera
		
			local SPEED_MULTIPLIER = 30
			local JUMP_POWER = 60
			local JUMP_GAP = 0.3
			local delta = 1
		
			local character = game.Players.LocalPlayer.Character or game.Players.LocalPlayer.CharacterAdded:Wait()
		
			for i, v in ipairs(character:GetDescendants()) do
				if v:IsA("BasePart") then
					v.CanCollide = false
					v.Transparency = 0
				end
			end
		
			local ball = character:WaitForChild("HumanoidRootPart")
			ball.Shape = Enum.PartType.Ball
			ball.Material = Enum.Material.SmoothPlastic
			ball.Size = Vector3.new(5, 5, 5)
			ball.Transparency = 0.75
		
			local humanoid = character:WaitForChild("Humanoid")
			local params = RaycastParams.new()
			params.FilterType = Enum.RaycastFilterType.Blacklist
			params.FilterDescendantsInstances = {character}
		
			local function updateMovement()
				local movement = Vector3.new(0, 0, 0)
		
				if UserInputService:IsKeyDown(Enum.KeyCode.W) then
					movement -= Camera.CFrame.LookVector
				end
				if UserInputService:IsKeyDown(Enum.KeyCode.S) then
					movement += Camera.CFrame.LookVector
				end
				if UserInputService:IsKeyDown(Enum.KeyCode.A) then
					movement -= Camera.CFrame.RightVector
				end
				if UserInputService:IsKeyDown(Enum.KeyCode.D) then
					movement += Camera.CFrame.RightVector
				end
		
				if movement.Magnitude > 0 then
					movement = movement.Unit * SPEED_MULTIPLIER
					ball.RotVelocity = Vector3.new(movement.X, ball.RotVelocity.Y, movement.Z)
				end
			end
		
			local movementConnection = RunService.RenderStepped:Connect(function(delta)
				ball.CanCollide = true
				humanoid.PlatformStand = true
		
				if not UserInputService:GetFocusedTextBox() then
					updateMovement()
				end
			end)
		
			UserInputService.JumpRequest:Connect(function()
				local result = workspace:Raycast(
					ball.Position,
					Vector3.new(0, -((ball.Size.Y / 2) + JUMP_GAP), 0),
					params
				)
		
				if result then
					ball.Velocity = ball.Velocity + Vector3.new(0, JUMP_POWER, 0)
				end
			end)
		
			Camera.CameraSubject = ball
			humanoid.Died:Connect(function()
				movementConnection:Disconnect()
			end)
		
		
		end)
	end;
	task.spawn(C_e9);
