							delete(Instance)
						end
						if Iris.SmallButton({"Clear children"}).clicked then
							for i,v in pairs(Instance:GetChildren()) do
								delete(v)
							end
						end
						Iris.End()
					end
		
					if InstTree.state.isUncollapsed.value then
