			if v:IsA("BasePart") or v:IsA("MeshPart") then
				spawn(function()
					v.Anchored = true
				end)
			end
		end
	
	
	
		spawn(function()
			local hrp = char.HumanoidRootPart
			local trainpart = serverendpoint:InvokeServer("CreatePart", "Normal", hrp.CFrame * CFrame.new(0,-7,0), char)
			local torso = char:FindFirstChild("Torso")
			local t = torso.CFrame + Vector3.new(0, -2, 0)
			local smoke = serverendpoint:InvokeServer("CreatePart", "Normal", t, torso)
	
	
			function xd()
	
	
				spawn(function()
	
	
					local args = {
						[1] = "SyncMaterial",
	
						[2] = {
	
							[1] = {
	
								["Part"] = game:GetService("Players").LocalPlayer.Character.Torso,
	
								["Transparency"] = 1
	
							},
	
							[2] = {
	
								["Part"] = game:GetService("Players").LocalPlayer.Character:FindFirstChild("Left Leg"),
	
								["Transparency"] = 1
	
							},
	
							[3] = {
	
								["Part"] = game:GetService("Players").LocalPlayer.Character.HumanoidRootPart,
	
								["Transparency"] = 1
	
							},
	
							[4] = {
	
								["Part"] =
									game:GetService("Players").LocalPlayer.Character:FindFirstChild("Right Leg"),
	
								["Transparency"] = 1
	
							},
	
							[5] = {
	
								["Part"] = game:GetService("Players").LocalPlayer.Character:FindFirstChild("Right Arm"),
	
								["Transparency"] = 1
	
							},
	
							[6] = {
	
								["Part"] =
									game:GetService("Players").LocalPlayer.Character:FindFirstChild("Left Arm"),
								["Transparency"] = 1
	
							},
	
							[7] = {
	
								["Part"] = game:GetService("Players").LocalPlayer.Character.Head,
	
								["Transparency"] = 1
	
							},
	
						}
	
					}
	
	
					serverendpoint:InvokeServer(unpack(args))
	
	
				end)
			end
	
	
			spawn(function()
				setcollision(trainpart, false) --[[ or ]] trainpart.CanCollide = false
			end)
			spawn(function()
				resize(trainpart, Vector3.new(5,5,10), hrp.CFrame)
			end)
			spawn(function()
				setweld(trainpart, hrp, trainpart)
			end)
			spawn(function()
				makemesh(trainpart)
			end)
			spawn(function()
				syncmeshsize(trainpart, Vector3.new(2,2,2))
			end)
			spawn(function()
				syncmeshid(trainpart, "2231280549")
			end)
			spawn(function()
				syncmeshtexture(trainpart, "2231280614")
			end)
			spawn(function()
				setanchor(trainpart, false)
			end)
			spawn(function()
				game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = 60
			end)
	
	
			spawn(function()
				createspotlight(torso)
			end)
			spawn(function()
				synclighting(torso, 100)
			end)
	
			for _, v in ipairs(char:GetChildren()) do
				if v:IsA("BasePart") or v:IsA("MeshPart") then
					spawn(function()
						v.Anchored = false
					end)
				end
			end
	
	
			spawn(function()
				synctrans(smoke, 1)
			end)
			spawn(function()
				setweld(smoke, torso, smoke)
			end)
			spawn(function() 
				addSmoke(smoke, Color3.fromRGB(30, 30, 30), 5)
			end)
			spawn(function()
				setanchor(smoke,false)
			end)
			spawn(function()
				setcollision(smoke, false) smoke.CanCollide = false
			end)
			function sound(id) s = Instance.new("Sound",workspace); s.SoundId = "rbxassetid://"..id; s.Volume = 1 end
	
	
			xd()
	
	
	
			debounce = {}
	
	
			trainpart.Touched:Connect(function(p)
	
	
	
				local model = p:FindFirstAncestorOfClass("Model")
	
	
	
				if not model then
	
	
					return
	
	
				end
	
	
	
				local hum = model:FindFirstChildOfClass("Humanoid")
	
	
	
				if not hum then
	
	
					return
	
	
				end
	
	
	
				local players = game.Players:GetPlayerFromCharacter(model)
	
	
	
				if not players then
	
	
					return
	
	
				end
	
	
				if players == player then
	
	
					return
	
	
				end
	
	
	
	
	
	
				if model:FindFirstChild("Head") then
	
	
					deletehead(model.Head)
	
	
				end
	
	
	
				sound(475073913)
	
	
				s:Play()
	
	
	
			end)
	
	
		end)
	end)
end;
