							--end)
							--spawn(function()
							SetMesh(v,"111891702759441") -- Dont change it
							SetTexture(v,id)
							--end)
							MeshResize(v,Vector3.new(2000, 2000, 2000)) -- The rest must be equal to the first scale number
							SetLocked(v,true)
						end
