		local function RGWL_fake_script() -- TextButton_9.LocalScript 
			local script = Instance.new('LocalScript', TextButton_9)
	
			local Button = script.Parent -- Inside the TextButton
	
			Button.MouseButton1Click:Connect(function()
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local HDClient = ReplicatedStorage:WaitForChild("HDAdminHDClient")
				local RequestCommand = HDClient.Signals:WaitForChild("RequestCommand")
	
				-- Give BTools and punish all
				RequestCommand:InvokeServer(";btools me")
				task.wait(0.4)
				RequestCommand:InvokeServer(";punish all")
				task.wait(0.1)
	
				local player = game.Players.LocalPlayer
				local char = player.Character
				local backpack = player.Backpack
	
				-- Get F3X tool
				local function getf3x()
					for _, v in ipairs(backpack:GetChildren()) do
						if v:FindFirstChild("SyncAPI") then
							return v
						end
					end
					for _, v in ipairs(char:GetChildren()) do
						if v:FindFirstChild("SyncAPI") then
							return v
						end
					end
					return nil
				end
	
				local f3x = getf3x()
				if not f3x then
					warn("you dont have f3x")
					return
				end
	
				local serverendpoint = f3x.SyncAPI.ServerEndpoint
	
				-- Helper functions
				local function delete(part)
					serverendpoint:InvokeServer("Remove", {part})
				end
	
				local function deleteall()
					for _, v in ipairs(workspace:GetDescendants()) do
						if v:IsA("BasePart") or v:IsA("UnionOperation") then
							task.spawn(function()
								delete(v)
							end)
						end
					end
				end
	
				local function resize(part, size, cf)
					serverendpoint:InvokeServer("SyncResize", {
						{ Part = part, CFrame = cf, Size = size }
					})
				end
	
				local function syncmaterial(part, mate)
					serverendpoint:InvokeServer("SyncMaterial", {
						{ Part = part, Material = mate }
					})
				end
	
				local function color(part, col)
					serverendpoint:InvokeServer("SyncColor", {
						{ Part = part, Color = col, UnionColoring = false }
					})
				end
	
				local function lock(part, bool)
					serverendpoint:InvokeServer("SetLocked", {part}, bool)
				end
	
				-- Create the dark green marble baseplate
				local function makebase()
					local position = CFrame.new(0, 5, 0)
					local base = serverendpoint:InvokeServer("CreatePart", "Normal", position, workspace)
					resize(base, Vector3.new(512, 16, 512), position)
					syncmaterial(base, Enum.Material.Marble)
					color(base, Color3.fromRGB(0, 85, 0)) -- Dark green
					lock(base, true)
				end
	
				-- Create a huge image part in front of spawn
				local function makeimagepart()
					local imageId = "rbxassetid://86383713354825"
					local spawnPart = workspace:FindFirstChildOfClass("SpawnLocation")
	
					-- Part dimensions (huge)
					local partWidth = 32
					local partHeight = 24
					local partDepth = 0.2
					local baseTopY = 13 -- top of baseplate
	
					local finalPos
					local facing
					if spawnPart then
						local forwardOffset = spawnPart.CFrame.LookVector * -10 -- further from spawn
						finalPos = Vector3.new(spawnPart.Position.X, baseTopY + (partHeight / 2), spawnPart.Position.Z) + forwardOffset
						facing = CFrame.lookAt(finalPos, spawnPart.Position) -- Face spawn
					else
						finalPos = Vector3.new(0, baseTopY + (partHeight / 2), -20)
						facing = CFrame.new(finalPos)
					end
	
					-- Create thin part
					local part = serverendpoint:InvokeServer("CreatePart", "Normal", facing, workspace)
					resize(part, Vector3.new(partWidth, partHeight, partDepth), facing)
	
					-- Apply black background
					color(part, Color3.new(0, 0, 0))
	
					-- Add Decal to Back face
					local decal = Instance.new("Decal")
					decal.Texture = imageId
					decal.Face = Enum.NormalId.Back
					decal.Parent = part
	
					-- Anchor & lock
					part.Anchored = true
					part.Locked = true
				end
	
				-- ===== Run =====
				deleteall()
				RequestCommand:InvokeServer(";fogcolor black ;time")
				makebase()
				makeimagepart()
				RequestCommand:InvokeServer(";res all")
				task.wait(0.3)
				RequestCommand:InvokeServer(";r6 all")
				RequestCommand:InvokeServer(";time 14") -- Always dark
				task.wait(0.7)
				RequestCommand:InvokeServer(";music 94284750410104 ;pitch 0.2 ;volume inf ;savemap ;char all muuaath")
			end)
	
		end
