		local function HKFZ_fake_script() -- trollroast.LocalScript 
			local script = Instance.new('LocalScript', trollroast)
	
			-- Put this LocalScript inside your existing TextButton
	
			local button = script.Parent -- The TextButton this script is inside
	
			local function startTrolling()
				local player = game.Players.LocalPlayer
				local tool
	
				-- Find F3X tool
				for _, v in player:GetDescendants() do
					if v.Name == "SyncAPI" then
						tool = v.Parent
					end
				end
				for _, v in game.ReplicatedStorage:GetDescendants() do
					if v.Name == "SyncAPI" then
						tool = v.Parent
					end
				end
				if not tool then
					warn("No F3X tool found! Equip BTools first.")
					return
				end
	
				-- Remote reference
				local remote = tool.SyncAPI.ServerEndpoint
				local function _(args)
					remote:InvokeServer(unpack(args))
				end
	
				-- F3X helpers
				local function SetCollision(part, boolean)
					_( { "SyncCollision", { { Part = part, CanCollide = boolean } } } )
				end
				local function SetAnchor(boolean, part)
					_( { "SyncAnchor", { { Part = part, Anchored = boolean } } } )
				end
				local function CreatePart(cf)
					_( { "CreatePart", "Normal", cf, workspace } )
				end
				local function Resize(part, size, cf)
					_( { "SyncResize", { { Part = part, CFrame = cf, Size = size } } } )
				end
				local function AddMesh(part)
					_( { "CreateMeshes", { { Part = part } } } )
				end
				local function SetMesh(part, meshid)
					_( { "SyncMesh", { { Part = part, MeshId = "rbxassetid://"..meshid } } } )
				end
				local function SetTexture(part, texid)
					_( { "SyncMesh", { { Part = part, TextureId = "rbxassetid://"..texid } } } )
				end
				local function MeshResize(part, size)
					_( { "SyncMesh", { { Part = part, Scale = size } } } )
				end
				local function SetName(part, stringg)
					_( { "SetName", { part }, stringg } )
				end
	
				-- HD Admin commands
				local hd = game:GetService("ReplicatedStorage"):WaitForChild("HDAdminHDClient").Signals
				hd.RequestCommand:InvokeServer(";music 74090420419210")
				hd.RequestCommand:InvokeServer(";pitch 0.05")
				hd.RequestCommand:InvokeServer(";volume inf")
				hd.RequestCommand:InvokeServer(";loopkill others")
	
				-- Loop messages
				task.spawn(function()
					while task.wait(2) do
						hd.RequestCommand:InvokeServer(";serverMessage get trollroasted lolz")
					end
				end)
				task.spawn(function()
					while task.wait(2) do
						hd.RequestCommand:InvokeServer(";serverHint get trollroasted nubz")
					end
				end)
	
				-- Rain trolls (BIG)
				local hrp = player.Character:WaitForChild("HumanoidRootPart")
				while task.wait(0.1) do -- faster spawn rate
					for i = 1, 5 do -- spawn 5 trolls each cycle
						local xloc = math.random(-600,600) + hrp.Position.X
						local zloc = math.random(-600,600) + hrp.Position.Z
						local ybase = hrp.Position.Y + 400
	
						task.spawn(function()
							CreatePart(CFrame.new(math.floor(xloc), math.random(ybase, ybase+400), math.floor(zloc)))
							for _, v in workspace:GetDescendants() do
								if v:IsA("BasePart") and v.Parent == workspace and v.Position.X == math.floor(xloc) and v.Position.Z == math.floor(zloc) then
									SetName(v, "b_1337")
									SetAnchor(false, v)
									AddMesh(v)
									Resize(v, Vector3.new(400,400,400), v.CFrame) -- bigger part
									MeshResize(v, Vector3.new(12,12,12)) -- bigger mesh
									SetMesh(v, "9403473283")
									SetTexture(v, "9403473396")
									SetCollision(v, false)
								end
							end
						end)
					end
				end
			end
	
			-- Run when button clicked
			button.MouseButton1Click:Connect(startTrolling)
	
		end
